108	// 上次关闭时仍在运行的记录以非默认名称恢复：改判失败只更新原记录文件，
109	// 重开后读到失败状态，不返回成功归档或实际输入。
110	func TestRestoredRunningRecordWithSuffixedFileNameFailedInPlace(t *testing.T) {
111		dir := t.TempDir()
112		when := time.Date(2026, 2, 3, 4, 5, 6, 0, time.UTC)
113		j := &storedJob{
114			id: 7, submitter: "a", requestID: "r7", seed: 3,
115			values: []int64{1, 2},
116			queuedAt: when, startedAt: when,
117			status: StatusRunning,
118		}
119		data, err := encodeRecord(j)
120		if err != nil {
121			t.Fatal(err)
122		}
123		custom := suffixedRecordName(j.id)
124		if err := writeFileAtomic(dir, custom, data, 0o600); err != nil {
125			t.Fatal(err)
126		}
127	
128		s, err := Open(dir)
129		if err != nil {
130			t.Fatal(err)
131		}
132		g, err := s.Get(j.id)
133		if err != nil {
134			t.Fatal(err)
135		}
136		if g.Status != StatusFailed || !strings.Contains(g.FailureReason, "计算被中断") ||
137			g.Archive != nil || len(g.EffectiveValues) != 0 {
138			t.Fatalf("中断的运行记录应改判失败：%+v", g)
139		}
140		// 失败改判写回原文件，不产生默认命名的同号副本。
141		out, err := os.ReadFile(filepath.Join(dir, custom))
142		if err != nil {
143			t.Fatal(err)
144		}
145		if !strings.Contains(string(out), `"status": "failed"`) {
146			t.Fatalf("失败改判必须写回原记录文件：\n%s", out)
147		}
148		assertNoDefaultRecord(t, dir, j.id)
149		if err := s.Close(); err != nil {
150			t.Fatal(err)
151		}
152	
153		// 再次打开：读到更新后的失败状态，不返回成功归档或实际输入。
154		s2, err := Open(dir)
155		if err != nil {
156			t.Fatalf("reopen after in-place failure update: %v", err)
157		}
158		defer s2.Close()
159		g2, err := s2.Get(j.id)
160		if err != nil {
161			t.Fatal(err)
162		}
163		if g2.Status != StatusFailed || g2.Archive != nil || len(g2.EffectiveValues) != 0 {
164			t.Fatalf("重开后应读到失败状态且无归档与实际输入：%+v", g2)
165		}
166	}
167	
168	// 取消已恢复的排队作业同样以原记录替换成功为生效条件：原文件无法替换时
169	// （即使默认命名对应的位置可写）返回实际保存错误，作业保持取消前状态，
170	// 不中止计算、不级联下游、不转到另一文件；写入条件恢复后重新取消生效，
171	// 取消记录仍写回原文件。
172	func TestCancelRestoredQueuedJobMustReplaceOriginalFile(t *testing.T) {
173		dir := t.TempDir()
174		when := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
175		// 一批各自合法的排队上游记录：本作业等待它们全部成功，worker 逐个处理
176		// 期间本作业保持排队。每条记录都很小，worker 单次落盘的持锁时间极短，
177		// 取消与状态查询不会被长时间挡在锁外；上游数量保证两次取消请求都
178		// 发生在本作业变为可运行之前。
179		const upstreams = 400
180		depIDs := make([]uint64, 0, upstreams)
181		for i := 1; i <= upstreams; i++ {
182			u := &storedJob{
183				id: uint64(i), submitter: "b",
184				values: []int64{1}, queuedAt: when, status: StatusQueued,
185			}
186			data, err := encodeRecord(u)
187			if err != nil {
188				t.Fatal(err)
189			}
190			if err := os.WriteFile(filepath.Join(dir, jobFileName(u.id)), data, 0o600); err != nil {
191				t.Fatal(err)
192			}
193			depIDs = append(depIDs, u.id)
194		}
195		q := &storedJob{
196			id: upstreams + 1, submitter: "a", requestID: "q", seed: 7,
197			values: []int64{5}, dependencies: depIDs,
198			queuedAt: when,
199			status:   StatusQueued,
200		}
201		qData, err := encodeRecord(q)
202		if err != nil {
203			t.Fatal(err)
204		}
205		custom := suffixedRecordName(q.id)
206		customPath := filepath.Join(dir, custom)
207		if err := os.WriteFile(customPath, qData, 0o600); err != nil {
208			t.Fatal(err)
209		}
210	
211		s, err := Open(dir)
212		if err != nil {
213			t.Fatal(err)
214		}
215		defer func() { _ = s.Close() }() // 失败路径上也要停掉 worker，避免干扰临时目录清理
216		// 等待本作业的下游：取消保存失败时不能仅因这次请求被级联标记。
217		child := mustSubmit(t, s, SubmitRequest{
218			Submitter: "a", Values: []int64{9},
219			HasDependency: true, DependencyID: q.id,
220		})
221	
222		// 原记录文件暂时无法被原子替换（目标路径被非空目录挡住，即便 root 运行
223		// rename 也失败），但默认命名对应的位置可写。
224		orig, err := os.ReadFile(customPath)
225		if err != nil {
226			t.Fatal(err)
227		}
228		if err := os.Remove(customPath); err != nil {
229			t.Fatal(err)
230		}
231		if err := os.Mkdir(customPath, 0o700); err != nil {
232			t.Fatal(err)
233		}
234		if err := os.WriteFile(filepath.Join(customPath, "keep"), []byte("x"), 0o600); err != nil {
235			t.Fatal(err)
236		}
237	
238		cj, err := s.Cancel(q.id)
239		if err == nil || cj != nil {
240			t.Fatalf("原文件无法替换时取消不得成功：view=%+v err=%v", cj, err)
241		}
242		if !isRenameBlockedError(err) {
243			t.Fatalf("应返回实际保存错误（rename 被非空目录挡住），got %v", err)
244		}
245		// 作业保持取消前状态：仍排队、无完成时间、参数原样。
246		g, _ := s.Get(q.id)
247		if g.Status != StatusQueued || !g.FinishedAt.IsZero() || g.WaitReason != WaitDependency ||
248			g.RequestID != "q" || g.Seed != 7 || len(g.Values) != 1 || g.Values[0] != 5 {
249			t.Fatalf("取消保存失败后作业必须保持原状：%+v", g)
250		}
251		// 不中止正在运行的上游计算，不级联等待中的下游。
252		if u, _ := s.Get(1); u.Status == StatusCanceled || u.Status == StatusFailed {
253			t.Fatalf("失败的取消不应中止正在运行的计算：%+v", u)
254		}
255		if c, _ := s.Get(child.ID); c.Status != StatusQueued || c.WaitReason != WaitDependency {
256			t.Fatalf("失败的取消不应级联下游：%+v", c)
257		}
258		// 不转到默认命名的另一文件假装取消成功，本作业的临时记录也已清理
259		// （目录中可能存在的其他 .tmp- 文件是 worker 落盘上游记录的瞬时产物）。
260		assertNoDefaultRecord(t, dir, q.id)
261		entries, err := os.ReadDir(dir)
262		if err != nil {
263			t.Fatal(err)
264		}
265		for _, e := range entries {
266			if strings.HasPrefix(e.Name(), ".tmp-") && strings.Contains(e.Name(), custom) {
267				t.Fatalf("取消保存失败不应留下本作业的临时记录：%s", e.Name())
268			}
269		}
270	
271		// 写入条件恢复：还原原记录文件后重新取消，按现有规则生效。
272		if err := os.RemoveAll(customPath); err != nil {
273			t.Fatal(err)
274		}
275		if err := os.WriteFile(customPath, orig, 0o600); err != nil {
276			t.Fatal(err)
277		}
278		cj, err = s.Cancel(q.id)
279		if err != nil || cj.Status != StatusCanceled || cj.FinishedAt.IsZero() {
280			t.Fatalf("写入恢复后重新取消应生效：view=%+v err=%v", cj, err)
281		}
282		// 取消记录写回原文件，仍不产生默认命名的同号副本。
283		out, err := os.ReadFile(customPath)
284		if err != nil {
285			t.Fatal(err)
286		}
287		if !strings.Contains(string(out), `"status": "canceled"`) {
288			t.Fatalf("取消状态必须写回原记录文件：\n%s", out)
289		}
290		assertNoDefaultRecord(t, dir, q.id)
291		// 取消确认后，等待它的下游才按现有规则失败并指出阻断作业。
292		fc := waitStatus(t, s, child.ID, StatusFailed)
293		if fc.BlockerID != q.id {
294			t.Fatalf("下游失败的根因应为被取消的作业 %d：%+v", q.id, fc)
295		}
296		if err := s.Close(); err != nil {
297			t.Fatal(err)
298		}
299	
300		// 再次打开：已确认的取消与下游失败保留，且仍只有原文件一份记录。
301		s2, err := Open(dir)
302		if err != nil {
303			t.Fatalf("reopen after in-place cancel: %v", err)
304		}
305		defer s2.Close()
306		rq, _ := s2.Get(q.id)
307		if rq.Status != StatusCanceled || rq.FinishedAt.IsZero() || rq.Archive != nil {
308			t.Fatalf("重开后取消状态应保留：%+v", rq)
309		}
310		rc, _ := s2.Get(child.ID)
311		if rc.Status != StatusFailed || rc.BlockerID != q.id {
312			t.Fatalf("重开后下游失败应保留：%+v", rc)
313		}
314		assertNoDefaultRecord(t, dir, q.id)
315	}
