38	// blockRenameWithDir 在目标正式记录路径放置一个非空目录，使“临时记录已
39	// 写好、却无法 rename 为正式记录”真实发生：临时文件仍可在归档目录中创建
40	// 和写盘，但替换目标被非空目录挡住（即便以 root 运行 rename 仍失败）。
41	// 返回清理函数。
42	func blockRenameWithDir(t *testing.T, dir string, id uint64) func() {
43		t.Helper()
44		target := filepath.Join(dir, jobFileName(id))
45		if err := os.Mkdir(target, 0o700); err != nil {
46			t.Fatalf("mkdir rename blocker: %v", err)
47		}
48		if err := os.WriteFile(filepath.Join(target, "keep"), []byte("x"), 0o600); err != nil {
49			t.Fatal(err)
50		}
51		return func() { _ = os.RemoveAll(target) }
52	}
53	
54	// isRenameBlockedError 判断错误是否为 rename 到非空目录时的实际保存错误。
55	// Linux 对“文件 rename 到已存在的非空目录”返回 EEXIST（空目录则为 EISDIR）。
56	func isRenameBlockedError(err error) bool {
57		return errors.Is(err, fs.ErrExist) ||
58			errors.Is(err, syscall.ENOTEMPTY) || errors.Is(err, syscall.EISDIR)
59	}
