1	package numeric
2	
3	import (
4		"strconv"
5		"strings"
6		"sync"
7		"testing"
8		"time"
9	)
10	
11	// setClock 是可随意拨动（含回拨）的测试时钟，用于模拟本机时钟异常。
12	type setClock struct {
13		mu sync.Mutex
14		t  time.Time
15	}
16	
17	func (c *setClock) Now() time.Time {
18		c.mu.Lock()
19		defer c.mu.Unlock()
20		return c.t
21	}
22	
23	func (c *setClock) set(t time.Time) {
24		c.mu.Lock()
25		defer c.mu.Unlock()
26		c.t = t
27	}
28	
29	// blockingCompute 占用计算位置，直到 Close 置位取消标记后返回失败；
30	// started 在首次进入计算时关闭，用于确认作业已在运行。
31	func blockingCompute(started chan<- struct{}) func(uint64, []int64, int64, func() bool) (int64, int64, string, bool) {
32		var once sync.Once
33		return func(_ uint64, _ []int64, _ int64, canceled func() bool) (int64, int64, string, bool) {
34			once.Do(func() { close(started) })
35			for !canceled() {
36				time.Sleep(time.Millisecond)
37			}
38			return 0, 0, "aborted", false
39		}
40	}
41	
42	// 时钟回拨后重新打开归档：调度顺序、按提交人列举的顺序都必须仍是
43	// 接受先后（作业号顺序），记录上的提交时间只用于范围过滤。
44	func TestReopenPreservesAcceptanceOrder(t *testing.T) {
45		dir := t.TempDir()
46		clock := &setClock{t: time.Date(2026, 10, 3, 9, 0, 0, 0, time.UTC)}
47		s, err := Open(dir, WithClock(clock))
48		if err != nil {
49			t.Fatalf("open: %v", err)
50		}
51		started := make(chan struct{})
52		s.compute = blockingCompute(started)
53	
54		// 占用本地唯一的计算位置，让后续作业留在队列里。
55		if _, err := s.Submit(SubmitRequest{Submitter: "bob", Values: []int64{1}}); err != nil {
56			t.Fatalf("submit blocker: %v", err)
57		}
58		<-started
59	
60		t1005 := time.Date(2026, 10, 3, 10, 5, 0, 0, time.UTC)
61		t1000 := time.Date(2026, 10, 3, 10, 0, 0, 0, time.UTC)
62	
63		clock.set(t1005)
64		ja, err := s.Submit(SubmitRequest{Submitter: "alice", Values: []int64{2}})
65		if err != nil {
66			t.Fatalf("submit A: %v", err)
67		}
68		// 时钟回拨：后接受的乙反而带着更早的提交时间。
69		clock.set(t1000)
70		jb, err := s.Submit(SubmitRequest{Submitter: "alice", Values: []int64{3}})
71		if err != nil {
72			t.Fatalf("submit B: %v", err)
73		}
74		// 提交时间完全相同的丙，接受顺序同样必须保留。
75		jc, err := s.Submit(SubmitRequest{Submitter: "alice", Values: []int64{4}})
76		if err != nil {
77			t.Fatalf("submit C: %v", err)
78		}
79		if jb.QueuedAt != jc.QueuedAt {
80			t.Fatalf("测试前提：乙丙提交时间应相同，got %v vs %v", jb.QueuedAt, jc.QueuedAt)
81		}
82		if err := s.Close(); err != nil {
83			t.Fatalf("close: %v", err)
84		}
85	
86		// 重新打开：甲、乙、丙都仍在排队，由新 worker 继续处理。
87		s2, err := Open(dir, WithClock(newManualClock()))
88		if err != nil {
89			t.Fatalf("reopen: %v", err)
90		}
91		defer func() { _ = s2.Close() }()
92	
93		a2 := waitStatus(t, s2, ja.ID, StatusSucceeded)
94		b2 := waitStatus(t, s2, jb.ID, StatusSucceeded)
95		c2 := waitStatus(t, s2, jc.ID, StatusSucceeded)
96		if !a2.StartedAt.Before(b2.StartedAt) || !b2.StartedAt.Before(c2.StartedAt) {
97			t.Fatalf("重新打开后执行顺序应为甲→乙→丙，got 甲@%v 乙@%v 丙@%v",
98				a2.StartedAt, b2.StartedAt, c2.StartedAt)
99		}
100	
101		// 不限范围：按实际提交顺序返回。
102		all, err := s2.List("alice", time.Time{}, time.Time{})
103		if err != nil {
104			t.Fatalf("list all: %v", err)
105		}
106		if len(all) != 3 || all[0].ID != ja.ID || all[1].ID != jb.ID || all[2].ID != jc.ID {
107			t.Fatalf("列举顺序应为甲、乙、丙，got %v", listIDs(all))
108		}
109	
110		// 范围只覆盖 10:00：只能查到乙、丙（按接受顺序）。
111		onlyBC, err := s2.List("alice", t1000, t1000)
112		if err != nil {
113			t.Fatalf("list 10:00: %v", err)
114		}
115		if len(onlyBC) != 2 || onlyBC[0].ID != jb.ID || onlyBC[1].ID != jc.ID {
116			t.Fatalf("10:00 范围内应只有乙、丙，got %v", listIDs(onlyBC))
117		}
118	
119		// 范围同时覆盖两个时间：先甲后乙丙，即使甲的记录时间更晚。
120		both, err := s2.List("alice", t1000, t1005)
121		if err != nil {
122			t.Fatalf("list 10:00-10:05: %v", err)
123		}
124		if len(both) != 3 || both[0].ID != ja.ID || both[1].ID != jb.ID || both[2].ID != jc.ID {
125			t.Fatalf("范围内列举应先甲后乙丙，got %v", listIDs(both))
126		}
127	
128		// 恢复不得改写提交时间，也不得重新分配作业号。
129		if !a2.QueuedAt.Equal(t1005) || !b2.QueuedAt.Equal(t1000) || !c2.QueuedAt.Equal(t1000) {
130			t.Fatalf("恢复后提交时间被改写：甲@%v 乙@%v 丙@%v", a2.QueuedAt, b2.QueuedAt, c2.QueuedAt)
131		}
132		if a2.ID != ja.ID || b2.ID != jb.ID || c2.ID != jc.ID {
133			t.Fatalf("恢复后作业号发生变化：%d/%d/%d", a2.ID, b2.ID, c2.ID)
134		}
135	}
136	
137	// 上次关闭时仍在运行的上游在恢复时变为失败：等待它的作业及更下游
138	// 必须在本次打开完成时级联失败，即使下游记录的提交时间更早。
139	func TestReopenCascadeWithRolledBackClock(t *testing.T) {
140		dir := t.TempDir()
141		clock := &setClock{t: time.Date(2026, 10, 3, 10, 5, 0, 0, time.UTC)}
142		s, err := Open(dir, WithClock(clock))
143		if err != nil {
144			t.Fatalf("open: %v", err)
145		}
146		started := make(chan struct{})
147		s.compute = blockingCompute(started)
148	
149		up, err := s.Submit(SubmitRequest{Submitter: "alice", Values: []int64{1}})
150		if err != nil {
151			t.Fatalf("submit up: %v", err)
152		}
153		<-started // up 正在运行，磁盘记录为 running
154	
155		// 时钟回拨：下游记录的提交时间早于上游。
156		clock.set(time.Date(2026, 10, 3, 10, 0, 0, 0, time.UTC))
157		mid, err := s.Submit(SubmitRequest{Submitter: "alice", Values: []int64{2}, Dependencies: []uint64{up.ID}})
158		if err != nil {
159			t.Fatalf("submit mid: %v", err)
160		}
161		clock.set(time.Date(2026, 10, 3, 9, 55, 0, 0, time.UTC))
162		down, err := s.Submit(SubmitRequest{Submitter: "alice", Values: []int64{3}, Dependencies: []uint64{mid.ID}})
163		if err != nil {
164			t.Fatalf("submit down: %v", err)
165		}
166	
167		// 模拟进程中断（不 Close）：磁盘上 up 仍是 running，mid/down 仍在排队。
168		// 直接重新打开同一目录，恢复应把 up 标记为失败并沿链条级联。
169		s2, err := Open(dir, WithClock(newManualClock()))
170		if err != nil {
171			t.Fatalf("reopen: %v", err)
172		}
173		defer func() { _ = s2.Close() }()
174		defer func() { _ = s.Close() }()
175	
176		up2 := waitStatus(t, s2, up.ID, StatusFailed)
177		mid2 := waitStatus(t, s2, mid.ID, StatusFailed)
178		down2 := waitStatus(t, s2, down.ID, StatusFailed)
179	
180		if !strings.Contains(up2.FailureReason, "计算被中断") {
181			t.Fatalf("上游失败原因应说明计算被中断，got %q", up2.FailureReason)
182		}
183		// 直接阻断者与根因作业号必须沿链条保留。
184		if mid2.BlockerID != up.ID {
185			t.Fatalf("mid 的根因作业号应为 %d，got %d", up.ID, mid2.BlockerID)
186		}
187		if !strings.Contains(mid2.FailureReason, "直接上游作业 "+itoa(up.ID)) {
188			t.Fatalf("mid 的失败详情应指出直接阻断者 %d，got %q", up.ID, mid2.FailureReason)
189		}
190		if down2.BlockerID != up.ID {
191			t.Fatalf("down 的根因作业号应为 %d，got %d", up.ID, down2.BlockerID)
192		}
193		if !strings.Contains(down2.FailureReason, "直接上游作业 "+itoa(mid.ID)) {
194			t.Fatalf("down 的失败详情应指出直接阻断者 %d，got %q", mid.ID, down2.FailureReason)
195		}
196		if !strings.Contains(down2.FailureReason, "根因为作业 "+itoa(up.ID)) {
197			t.Fatalf("down 的失败详情应保留根因作业号 %d，got %q", up.ID, down2.FailureReason)
198		}
199	
200		// 级联后的列举仍按接受顺序。
201		all, err := s2.List("alice", time.Time{}, time.Time{})
202		if err != nil {
203			t.Fatalf("list: %v", err)
204		}
205		if len(all) != 3 || all[0].ID != up.ID || all[1].ID != mid.ID || all[2].ID != down.ID {
206			t.Fatalf("列举顺序应为上游→中游→下游，got %v", listIDs(all))
207		}
208	}
209	
210	func listIDs(jobs []*Job) []uint64 {
211		ids := make([]uint64, 0, len(jobs))
212		for _, j := range jobs {
213			ids = append(ids, j.ID)
214		}
215		return ids
216	}
217	
218	func itoa(id uint64) string {
219		return strconv.FormatUint(id, 10)
220	}
